/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"bassstation-level-18","number":18,"title":"DAW Studio Integration, SysEx Librarian, Diagnostic Troubleshooting & Capstone Project","skillBand":"Textbook","duration":"From the course textbook","summary":"- Configure an isolated, latency-optimized hardware tracking session in Ableton Live 12 Standard. - Route mono analogue audio from LINE OUTPUT into a dedicated Live 12 Audio Track with appropriate gain staging.","modules":[{"id":"bassstation-m-18-1","code":"18","title":"DAW Studio Integration, SysEx Librarian, Diagnostic Troubleshooting & Capstone Project","blurb":"- Configure an isolated, latency-optimized hardware tracking session in Ableton Live 12 Standard. - Route mono analogue audio from LINE OUTPUT into a dedicated Live 12 Audio Track with appropriate gain staging.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"bassstation-l-o-18","title":"Section overview","blocks":[{"type":"step","title":"Section 18.1 — Ableton Live 12 Standard Integration","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Configure an isolated, latency-optimized hardware tracking session in <strong>Ableton Live 12 Standard</strong>.","Route mono analogue audio from <code>LINE OUTPUT</code> into a dedicated Live 12 Audio Track with appropriate gain staging.","Route bidirectional USB MIDI between Live 12 and the synthesizer using <code>Local Off</code> to prevent MIDI echo doubling.","Automate hardware filter cutoff, resonance, distortion, and oscillator parameters using standard MIDI CC and 14-bit NRPN messages.","Synchronize the Bass Station II's internal arpeggiator, 32-step sequencer, and synced LFOs to Live 12's master transport clock."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-1-1","title":"18.1.1: Analogue Audio Tracking into Live 12 Standard","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II is a pure monophonic analogue synthesizer:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                      STUDIO AUDIO TRACKING TOPOLOGY\n   [Bass Station II LINE OUT (¼\" TS)]\n                 │\n                 ▼ (Unbalanced TS Instrument / Line Cable)\n   [Audio Interface Input 1 (Mono Line Level)]\n                 │\n                 ▼ (ASIO / CoreAudio Driver: 44.1/48 kHz, 128 Buffer)\n   [Ableton Live 12 Audio Track]\n     • Audio From: `Ext. In` -&gt; `1 (Mono)`\n     • Monitor: `Auto` or `Off` (Direct Hardware Monitoring)\n     • Peak Target Level: `-18 dBFS to -12 dBFS` (Preserves Headroom)</pre>"},{"type":"list","items":["<strong>Mono Channel Configuration</strong>:","In Live 12, create an <strong>Audio Track</strong> (<code>Ctrl + T</code> / <code>Cmd + T</code>).","In the track's I/O section, set <strong>Audio From</strong> to <code>Ext. In</code> and choose the mono input channel (e.g., <code>1</code>).","Do not select a stereo input pair (e.g., <code>1/2</code>); the hardware line output is strictly unbalanced monophonic.","<strong>Gain Staging Target</strong>:","Calibrate the hardware Master Volume and audio interface preamp gain so that aggressive resonant filter peaks register between <strong>-18 dBFS and -12 dBFS</strong> in Live 12's track meter, ensuring zero digital clipping at the A/D converters."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-1-2","title":"18.1.2: Bidirectional MIDI Configuration & Local Off Protocol","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"To record and play back MIDI without note-doubling or envelope glitching:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                      STUDIO MIDI ROUTING ARCHITECTURE\n   [Bass Station II Hardware] ──► (Local Control = OFF)\n         │                                  ▲\n         │ (Keybed Strike / Knob Movement)   │ (Echoes MIDI Back)\n         ▼                                  │\n   [USB MIDI Cable]                         │\n         │                                  │\n         ▼                                  │\n   [Ableton Live 12 MIDI Track] ────────────┘\n     • MIDI From: `Bass Station II` -&gt; `Ch. 1`\n     • Monitor: `In` or `Auto` (Record-Armed)\n     • MIDI To: `Bass Station II` -&gt; `Ch. 1`</pre>"},{"type":"list","items":["<strong>Live 12 MIDI Preferences</strong>:","Open <strong>Settings</strong> (<code>Ctrl + ,</code> / <code>Cmd + ,</code>) -&gt; <strong>Link, Tempo &amp; MIDI</strong>.","Under <strong>MIDI Ports</strong>:","<code>Input: Bass Station II</code> -&gt; Enable <strong>Track</strong> (for recording notes) and <strong>Remote</strong> (for MIDI learn/CC).","<code>Output: Bass Station II</code> -&gt; Enable <strong>Track</strong> (for playback) and <strong>Sync</strong> (for sending MIDI clock).","<strong>Local Off Execution</strong>:","On the Bass Station II, press <strong>Function / Exit</strong>, press upper <code>A</code> (<strong>Local</strong>), set value to <code>OFF</code>, and exit Function mode.","Now, keys struck on the keybed travel into Live 12, are recorded on the armed MIDI track, and are echoed back to the Bass Station II sound engine without double-triggering."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-1-3","title":"18.1.3: Parameter Automation via MIDI CC & NRPN","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Every physical knob, fader, and switch on the Bass Station II transmits and responds to standard MIDI Control Change (CC) or Non-Registered Parameter Number (NRPN) messages."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    PRIMARY HARDWARE MIDI CC AUTOMATION MAP                 │\n├──────────────────────┬─────────────┬─────────────┬─────────────────────────┤\n│ Synthesis Parameter  │ MIDI CC #   │ Data Range  │ Description             │\n├──────────────────────┼─────────────┼─────────────┼─────────────────────────┤\n│ Mod Wheel            │ CC 1        │ `0–127`     │ Real-time mod wheel     │\n│ Portamento Time      │ CC 5        │ `0–127`     │ Glide slew rate         │\n│ Filter Frequency     │ CC 16       │ `0–127`     │ Filter Cutoff dial      │\n│ Filter Resonance     │ CC 82       │ `0–127`     │ Filter Resonance pot    │\n│ Pre-Filter Overdrive │ CC 87       │ `0–127`     │ Overdrive gain          │\n│ Post-Distortion      │ CC 91       │ `0–127`     │ Analogue Distortion     │\n│ Osc Filter Mod       │ CC 74       │ `0–127`     │ Osc 2 to Filter FM      │\n│ Osc 1 Level (Mixer)  │ CC 20       │ `0–127`     │ Mixer Osc 1 level       │\n│ Osc 2 Level (Mixer)  │ CC 21       │ `0–127`     │ Mixer Osc 2 level       │\n│ Sub-Osc Level (Mixer)│ CC 22       │ `0–127`     │ Mixer Sub level         │\n│ Amp Env Attack       │ CC 73       │ `0–127`     │ Amp Attack fader        │\n│ Amp Env Decay        │ CC 75       │ `0–127`     │ Amp Decay fader         │\n│ Amp Env Sustain      │ CC 70       │ `0–127`     │ Amp Sustain fader       │\n│ Amp Env Release      │ CC 72       │ `0–127`     │ Amp Release fader       │\n└──────────────────────┴─────────────┴─────────────┴─────────────────────────┘</pre>"},{"type":"list","items":["<strong>Drawing Automation in Live 12</strong>:","In Live 12 Clip View or Arrangement View, open the <strong>Envelopes / Automation</strong> lane.","Select <code>MIDI Control</code> -&gt; choose <code>CC 16 (Filter Cutoff)</code> or <code>CC 82 (Resonance)</code>.","Draw precise automation curves; as Live 12 plays back, the synthesizer's analog filter sweeps in exact synchronization with the drawn curves."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-1-4","title":"18.1.4: Master Clock Synchronization","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Clock Configuration</strong>:","In Live 12 Preferences, ensure <strong>Sync</strong> is enabled for <code>Output: Bass Station II</code>.","<strong>Hardware Response</strong>:","When Live 12 starts playback (<code>Spacebar</code>), the Bass Station II automatically locks its internal tempo engine to Live's transport.","Setting LFOs to <code>Snc</code> locks modulation rates (e.g., <code>8n</code>, <code>16n</code>) to Live's bar grid.","Launching the Arpeggiator or 32-Step Sequencer synchronizes notes to the global DAW tempo."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-1-5","title":"18.1.5: Control Surface Operational Boundary","blocks":[{"type":"step","title":"18.1.5: Control Surface Operational Boundary","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"callout","variant":"key","title":"Note","html":"[!IMPORTANT] The Bass Station II is <strong>not a dedicated Ableton Live DAW control surface</strong>. It does not feature motorized faders, clip-launching pads, or Launchkey-style DAW integration scripts. It functions as an external analogue MIDI sound generator and standard MIDI master keyboard."}]},{"type":"step","title":"Section 18.2 — Novation Components Librarian and SysEx Backup","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Execute complete 128-patch bank backups using Novation Components.","Audition cloud and librarian patches in real time using the <strong>Preview</strong> load function without overwriting internal memory.","Transmit individual patches (<code>OnE</code>) and full banks (<code>All</code>) directly from hardware via On-Key <strong>SysEx Dump</strong>.","Safeguard against accidental library overwriting during SysEx imports."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-2-1","title":"18.2.1: Librarian Management in Novation Components","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Get from Device</strong>:","Open Components (with green connection). Navigate to the <strong>Patches</strong> tab.","Click <strong>Get from Bass Station II</strong>. Components reads all 128 patch slots from hardware flash memory and displays them in a graphical grid.","<strong>Send to Device</strong>:","Drag and drop custom patches or load an archived <code>.syx</code> bank file.","Click <strong>Send to Bass Station II</strong> to flash the bank into the synthesizer's non-volatile memory."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-2-2","title":"18.2.2: The Real-Time Preview Feature","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["Inside Components, clicking the <strong>Speaker Icon</strong> next to any patch in your library transmits that sound temporarily into the Bass Station II's <strong>volatile edit buffer</strong>.","You can immediately play the keybed to audition the sound.","<em>Safety Rule</em>: Previewing <strong>does not overwrite the stored patch on the hardware</strong> unless you physically press the hardware <strong>Save</strong> button twice."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-2-3","title":"18.2.3: Hardware System Exclusive (SysEx) Dumps","blocks":[{"type":"step","title":"18.2.3: Hardware System Exclusive (SysEx) Dumps","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"To back up patches directly without using Novation Components:"},{"type":"list","items":["Connect the synthesizer via USB or 5-Pin DIN MIDI OUT to a computer running a SysEx utility (e.g., MIDI-OX or Snoize SysEx Librarian).","Set the software to \"Record SysEx\".","Press <strong>Function / Exit</strong>, then press the <strong>Dump</strong> key (the highest <code>C</code> key, Key 25).","The display shows <strong><code>OnE</code></strong> (dumps only the current active patch) or <strong><code>All</code></strong> (dumps all 128 patches in a single SysEx stream).","Use <strong>Patch/Value ▲ and ▼</strong> to choose, then press <strong>Function / Exit</strong> to execute the dump."],"ordered":true}]},{"type":"step","title":"Section 18.3 — Comprehensive Troubleshooting Diagnostic Trees","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Systematically diagnose and resolve complete audio loss across physical and digital signal paths.","Troubleshoot USB enumeration, driver conflicts, and Web MIDI browser errors.","Resolve envelope looping failures using established override rules.","Recover synthesizers stuck in Bootloader mode."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-3-1","title":"18.3.1: Master Audio Signal Flow Diagnostic Tree","blocks":[{"type":"step","title":"18.3.1: Master Audio Signal Flow Diagnostic Tree","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                       MASTER \"NO SOUND\" FAULT TREE\n ┌────────────────────────────────────────────────────────────────────────────┐\n │ 1. Master Volume turned up? (Analog pot: check 10 o'clock position)       │\n │    └── No ──► Turn Volume up.                                             │\n │ 2. Mixer levels active? (Osc 1, Osc 2, Sub, or Noise &gt; 0)                 │\n │    └── No ──► Raise individual source levels in Mixer.                    │\n │ 3. Filter closed with zero modulation? (Frequency at 0, Mod Env at 0)     │\n │    └── Yes ──► Open Filter Frequency dial to 50–100%.                     │\n │ 4. Local Control turned OFF with no DAW MIDI echo?                        │\n │    └── Yes ──► Power cycle unit to restore Local Control to ON.           │\n │ 5. VCA Amp Envelope closed? (Attack high, Decay 0, Sustain 0)             │\n │    └── Yes ──► Set Sustain fader to 100% (Maximum).                       │\n │ 6. Audio cable inserted into EXT IN instead of LINE OUTPUT?               │\n │    └── Yes ──► Verify cable is firmly in LINE OUTPUT (MONO).              │\n └────────────────────────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"bassstation-l-18-3-2","title":"18.3.2: USB & Components Recognition Diagnostics","blocks":[{"type":"step","title":"18.3.2: USB & Components Recognition Diagnostics","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    USB &amp; COMPONENTS TROUBLESHOOTING                        │\n├─────────────────────────┬──────────────────────────────────────────────────┤\n│ Symptom                 │ Root Cause &amp; Corrective Procedure                │\n├─────────────────────────┼──────────────────────────────────────────────────┤\n│ Components Status RED   │ 1. Check USB A-to-B cable connection.            │\n│                         │ 2. Ensure rear switch is set to `ext DC` or `USB`│\n│                         │ 3. Bypass unpowered USB hubs; connect direct.    │\n├─────────────────────────┼──────────────────────────────────────────────────┤\n│ Components Status YELLOW│ 1. Another DAW is locking the MIDI port. Close   │\n│                         │    all DAWs and background MIDI utilities.       │\n│                         │ 2. Unit is in Bootloader mode (display `bLt`).   │\n├─────────────────────────┼──────────────────────────────────────────────────┤\n│ Browser says \"Web MIDI  │ 1. Safari and Firefox are NOT supported. Use     │\n│ Not Supported\"          │    Google Chrome, Microsoft Edge, or Opera.      │\n│                         │ 2. Grant browser MIDI device permissions.        │\n└─────────────────────────┴──────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"bassstation-l-18-3-3","title":"18.3.3: Envelope Retriggering Diagnostics","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Symptom</strong>: You enabled Envelope Retriggering (<code>r-1</code>), but the envelope executes only once and fails to loop.","<strong>Root Cause</strong>: <strong>Fixed-Duration Sustain (<code>d-1</code>) is currently active on that envelope</strong>.","<strong>Corrective Action</strong>: Access the envelope menu with 4 presses (<code>Function</code> + 4 taps on Amp/Mod Env key); set the display to <strong><code>d-0</code></strong>. Envelope looping will immediately restore."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-3-4","title":"18.3.4: Bootloader Mode Recovery Protocol","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["If the synthesizer boots with the display showing <strong><code>bLt</code></strong> or <strong><code>UPd</code></strong>, the microprocessor has entered its hardware Bootloader recovery state.","<strong>Recovery Step 1</strong>: Press the <strong>On / Legato (Play)</strong> button. In many cases, this forces the processor to exit the bootloader and boot standard firmware.","<strong>Recovery Step 2</strong>: If the unit remains in bootloader mode, connect USB, open Novation Components, and execute a clean firmware re-installation."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-3-5","title":"18.3.5: Official Novation Support Resources","blocks":[{"type":"step","title":"18.3.5: Official Novation Support Resources","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                      OFFICIAL SUPPORT INFRASTRUCTURE                       │\n├───────────────────────────────┬────────────────────────────────────────────┤\n│ Resource Domain               │ Authoritative URL                          │\n├───────────────────────────────┼────────────────────────────────────────────┤\n│ Easy Start &amp; Registration     │ `getstarted.novationmusic.com`             │\n│ Novation Components Platform  │ `components.novationmusic.com`             │\n│ Official Drivers &amp; Software   │ `downloads.novationmusic.com/novation`     │\n│ Technical Support Help Centre │ `support.novationmusic.com`                │\n└───────────────────────────────┴────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Section 18.4 — Capstone Project & Written Settings Documentation","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Synthesize all course proficiencies into a finished 60–90 second recorded musical performance.","Document complete hardware patch parameters, On-Key offsets, AFX overlay mappings, and DAW routing on a standardized settings sheet.","Export and archive non-volatile patch data via Novation Components or SysEx."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-4-1","title":"18.4.1: Capstone Project Brief (Assessment Gate J)","blocks":[{"type":"step","title":"1. Project Specifications","blocks":[{"type":"prose","html":"To complete the course and achieve <strong>Gate J Certification</strong>, the student must produce a finished, cohesive <strong>60–90 second recorded performance</strong> incorporating:"},{"type":"list","items":["<strong>Original Analogue Sound Design</strong>: An original bass or lead patch built from an initialized user slot (<code>64</code>–<code>127</code>), utilizing both primary oscillators, sub-oscillator detuning, and custom ADSR envelopes.","<strong>Dynamic Filter Modulation</strong>: Real-time or automated cutoff modulation incorporating either pre-filter Overdrive, Acid diode-ladder resonance, or Osc Filter Mod (FM).","<strong>Sequencing or AFX Drum Workstation</strong>: Either a recorded 32-step sequence (with rests and ties), a complex arpeggiated groove with Swing, or a custom-designed AFX Mode per-key drum kit.","<strong>Ableton Live 12 Recording</strong>: Simultaneous mono analogue audio capture and MIDI note/automation recording."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-18-4-2","title":"18.4.2: Standardized Hardware Settings Sheet","blocks":[{"type":"step","title":"18.4.2: Standardized Hardware Settings Sheet","blocks":[{"type":"prose","html":"The student must submit a complete settings sheet accompanying the capstone audio file:"}]}],"minutes":8},{"id":"bassstation-l-h","title":"Hardware Settings Sheet","blocks":[{"type":"step","title":"Hardware Settings Sheet","blocks":[{"type":"list","items":["<strong>Author</strong>: [Student Name]","<strong>Target User Patch Slot</strong>: [e.g., Slot 105]","<strong>Power Configuration</strong>: [Supplied 9 V DC PSU via <code>ext DC</code>]","<strong>Global MIDI Channel</strong>: [e.g., Channel 1]","<strong>Local Control State</strong>: [Local OFF during DAW tracking]","<strong>Oscillator Configuration</strong>:","Osc 1: [Sawtooth, 8' Range, Pitch Mod: 0]","Osc 2: [Square, 8' Range, Coarse: 0, Fine: +8 cents, Pitch Mod: 0]","Sub-Oscillator: [Square, -1 Octave, Sub Detune: 0]","Hard Sync: [OFF] | Paraphonic Mode: [P-0] | Osc Error: [E-2]","<strong>Mixer Balance</strong>:","Osc 1: [100] | Osc 2: [85] | Sub: [70] | Noise/Ring/Ext: [Noise at 15]","<strong>Filter Configuration</strong>:","Type: [Classic] | Shape: [LP] | Slope: [24 dB]","Cutoff Frequency: [45%] | Resonance: [60%] | Overdrive: [35%]","Mod Env Depth: [+32 (2 Octaves)] | LFO 2 Depth: [0]","Filter Tracking: [F-0 (100%)]","<strong>Envelopes</strong>:","Amp ADSR: [A: 0ms, D: 400ms, S: 80%, R: 250ms] | Trigger: [Autoglide]","Mod ADSR: [A: 0ms, D: 250ms, S: 0%, R: 100ms]","Looping: [r-0] | Fixed Sustain: [d-0]","<strong>Effects &amp; Portamento</strong>:","Distortion: [25] | Osc Filter Mod: [0] | Glide Time: [35%] (Divergence: g-0)","<strong>LFO Settings</strong>:","LFO 1: [Triangle, Speed: SPd at 5.5 Hz, Delay: 1.2s, Keysync: On]","LFO 2: [Sawtooth, Speed: Snc at 8n, Keysync: On]","<strong>AFX Mode / Sequencer</strong>:","AFX Overlay Bank: [o-0 (Disabled) or o-5 (Custom 4-Key Drum Kit)]","Sequencer Bank: [SEQ 1: 16 Steps, Rhythm Pattern: 7, SEQ Retrig: On]","<strong>DAW Configuration (Ableton Live 12 Standard)</strong>:","Audio Track: [Mono Input 1, Buffer 128 samples, Peak -14 dBFS]","MIDI Automation: [CC 16 Filter Cutoff lane automated across bars 1–16]"],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">\n---</pre>"}]}],"minutes":8},{"id":"bassstation-l-18-4-3","title":"18.4.3: SysEx / Components Backup Verification","blocks":[{"type":"step","title":"18.4.3: SysEx / Components Backup Verification","blocks":[{"type":"list","items":["The student must perform a full bank backup via Novation Components or execute an On-Key <code>Dump: All</code> to archive the capstone patch into a <code>.syx</code> file."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-18-4-4","title":"18.4.4: Academic Course Reflection","blocks":[{"type":"step","title":"18.4.4: Academic Course Reflection","blocks":[{"type":"list","items":["Identify three hardware synthesis features mastered during the course.","Document one technical edge-case resolved (e.g., Local Off MIDI echo resolution, Fixed Sustain envelope looping override, or external clock Flywheel takeover)."],"ordered":false}]},{"type":"step","title":"Assessment Gate J — Final Capstone Certification","blocks":[{"type":"prose","html":"Verify complete execution of all Gate J criteria:"},{"type":"list","items":["[ ] <strong>Acoustic Production</strong>: 60–90 second recorded audio file demonstrating discrete analog synthesis, filter modulation, and sequencing/AFX performance.","[ ] <strong>DAW MIDI Capture</strong>: Multi-lane MIDI automation captured cleanly in Ableton Live 12 Standard.","[ ] <strong>Settings Documentation</strong>: Complete, reproducible Hardware Settings Sheet.","[ ] <strong>Library Archive</strong>: Valid <code>.syx</code> patch backup verified in Novation Components."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
